import { useEffect, useRef, useState } from "react";
import "./App.css";
import DangerAlert from "./components/alerts/DangerAlert";
import EndTestAlert from "./components/alerts/EndTestAlert";
import SuccesAlert from "./components/alerts/SuccesAlert";
import ChoiceTest from "./components/choiceTest/ChoiceTest";
import Footer from "./components/footer/Footer";
import Header from "./components/header/Header";
import LimitOfquestions from "./components/limitOfquestions/LimitOfquestions";
import Quiz from "./components/quiz/Quiz.js";
import ProgressStats from "./components/quiz/ProgressStats";
import ResultsButtons from "./components/quiz/ResultsButtons";
import SessionHistory from "./components/quiz/SessionHistory";
import MetroMap from "./components/quiz/MetroMap";
import PreExamBriefing from "./components/quiz/PreExamBriefing";
import Refresh from "./components/refreshQuiz/RefreshQuiz.js";
import SoundOnOff from "./components/soundOnOff/SoundOnOff.js";
import StyleToggle from "./components/styleToggle/StyleToggle.js";
import ThemeToggle from "./components/themeToggle/ThemeToggle.js";
import WrongAnswers from "./components/wrongAnswers/WrongAnswers";
import SearchBar from "./components/searchBar/SearchBar";
import { CATEGORIES, VISUAL_STYLES, STORAGE_KEYS, EXAM_TOTAL_COUNT, EXAM_SYGNALIZACJA_COUNT, MIN_QUESTIONS_FOR_STATS } from "./constants";
import { draw, getStarredIds, toggleStarred, saveSession, getWeakestQuestions, updateQuestionStat, savePausedSession, loadPausedSession, clearPausedSession, getQuestionId, migrateStorageToIds, remapPausedSession } from "./utils/quizUtils";
import oklaski from "./sound/oklaski.mp3";
import smiech from "./sound/smiech.mp3";

function App() {
  const [allQuestions, setAllQuestions] = useState([]);
  const [currentTest, setCurrentTest] = useState([]);
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [maxQuestions, setMaxQuestions] = useState(0);
  const [endTest, setEndTest] = useState(false);
  const [audio, setAudioOn] = useState(false);
  const [correctAnswers, setCorectAnswers] = useState(0);
  const [inCorrectAnswers, setInCorrectAnswers] = useState(0);
  const [dangerAlert, setDangerAlert] = useState(false);
  const [succesAlert, setSuccesAlert] = useState(false);
  const [isDisabled, setIsDisabled] = useState(false);
  const [test, setTest] = useState(["all"]);
  const [categoryLimits, setCategoryLimits] = useState({});
  const [wrongAnswers, setWrongAnswers] = useState([]);
  const [showWrongAnswers, setShowWrongAnswers] = useState(false);
  const [isManualLimit, setIsManualLimit] = useState(false);
  const [fullFilteredLength, setFullFilteredLength] = useState(0);
  const [selectedAnswerIndex, setSelectedAnswerIndex] = useState(null);
  const [isAnswerCorrect, setIsAnswerCorrect] = useState(null);
  const [hasSygnalizacjaError, setHasSygnalizacjaError] = useState(false);
  const [examMode, setExamMode] = useState(false);
  const [learningMode, setLearningMode] = useState(false);
  const [totalAnswered, setTotalAnswered] = useState(0);
  const [starredIds, setStarredIds] = useState(() => getStarredIds());
  const [showHistory, setShowHistory] = useState(false);
  const [showMap, setShowMap] = useState(false);
  const [showBriefing, setShowBriefing] = useState(false);
  const [weakestMode, setWeakestMode] = useState(false);
  const [isMistakesReview, setIsMistakesReview] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [pausedSession, setPausedSession] = useState(() => loadPausedSession());
  const [learningWrongClicks, setLearningWrongClicks] = useState(new Set());
  const resumingRef = useRef(false);

  const [theme, setTheme] = useState(() => localStorage.getItem(STORAGE_KEYS.theme) || "dark");
  const [visualStyle, setVisualStyle] = useState(() => localStorage.getItem(STORAGE_KEYS.visualStyle) || "default");

  useEffect(() => { localStorage.setItem(STORAGE_KEYS.theme, theme); }, [theme]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.visualStyle, visualStyle); }, [visualStyle]);

  const toggleTheme = () => setTheme((prev) => (prev === "light" ? "dark" : "light"));

  const toggleVisualStyle = () => {
    setVisualStyle((prev) => {
      const currentIndex = VISUAL_STYLES.indexOf(prev);
      const nextIndex = currentIndex === -1 ? 0 : (currentIndex + 1) % VISUAL_STYLES.length;
      return VISUAL_STYLES[nextIndex];
    });
  };

  const handleTest = (e) => {
    setExamMode(false);
    const value = e.target.value;
    setTest((prev) => {
      if (value === "all") return ["all"];
      const next = prev.includes("all") ? [] : [...prev];
      if (next.includes(value)) {
        const filtered = next.filter((v) => v !== value);
        return filtered.length === 0 ? ["all"] : filtered;
      }
      return [...next, value];
    });
  };

  const sound = useRef(typeof Audio !== "undefined" ? new Audio(oklaski) : null);
  const sound2 = useRef(typeof Audio !== "undefined" ? new Audio(smiech) : null);

  // Resetuje stan quizu do wartości początkowych
  const resetQuizState = () => {
    setCorectAnswers(0);
    setInCorrectAnswers(0);
    setCurrentQuestion(0);
    setEndTest(false);
    setDangerAlert(false);
    setSuccesAlert(false);
    setIsDisabled(false);
    setHasSygnalizacjaError(false);
    setSelectedAnswerIndex(null);
    setIsAnswerCorrect(null);
    setWrongAnswers([]);
    setShowWrongAnswers(false);
    setTotalAnswered(0);
    setWeakestMode(false);
    setIsMistakesReview(false);
    setLearningWrongClicks(new Set());
  };

  const answerChange = (answerUser) => {
    if (currentQuestion >= maxQuestions + 1) return;
    setSelectedAnswerIndex(answerUser);

    if (answerUser === currentTest[currentQuestion].correct) {
      setIsDisabled(true);
      setTotalAnswered((prev) => prev + 1);
      if (audio && sound.current) {
        sound.current.currentTime = 0;
        sound.current.play();
      }
      updateQuestionStat(currentTest[currentQuestion], true);
      setCorectAnswers(correctAnswers + 1);
      setIsAnswerCorrect(true);
      if (learningMode) {
        setTimeout(() => nextQuestionRef.current(), 700);
      } else {
        setSuccesAlert(true);
      }
    } else {
      if (learningMode) {
        // Blokujemy tylko kliknięty zły przycisk, użytkownik szuka poprawnej
        setLearningWrongClicks((prev) => new Set([...prev, answerUser]));
        updateQuestionStat(currentTest[currentQuestion], false);
      } else {
        setIsDisabled(true);
        setTotalAnswered((prev) => prev + 1);
        if (audio && sound2.current) {
          sound2.current.currentTime = 0;
          sound2.current.play();
        }
        const currentCategories = Array.isArray(currentTest[currentQuestion]?.category)
          ? currentTest[currentQuestion].category
          : [currentTest[currentQuestion]?.category];
        if (currentCategories.includes("sygnalizacja")) {
          setHasSygnalizacjaError(true);
        }
        updateQuestionStat(currentTest[currentQuestion], false);
        setIsAnswerCorrect(false);
        setDangerAlert(true);
        if (inCorrectAnswers + correctAnswers < maxQuestions) {
          setInCorrectAnswers(inCorrectAnswers + 1);
        }
        setWrongAnswers([...wrongAnswers, currentTest[currentQuestion]]);
      }
    }
  };

  const nextQuestion = () => {
    if (currentQuestion + 1 === maxQuestions) {
      clearPausedSession();
      setPausedSession(null);
      setDangerAlert(false);
      setSuccesAlert(false);
      setEndTest(true);
      return;
    }
    const snapshot = {
      currentTest,
      currentQuestion: currentQuestion + 1,
      correctAnswers,
      inCorrectAnswers,
      wrongAnswers,
      test,
      maxQuestions,
      examMode,
      weakestMode,
      isMistakesReview,
      learningMode,
      totalAnswered,
      hasSygnalizacjaError,
      savedAt: new Date().toISOString(),
    };
    savePausedSession(snapshot);
    setPausedSession(snapshot);
    setCurrentQuestion(currentQuestion + 1);
    setSelectedAnswerIndex(null);
    setIsAnswerCorrect(null);
    setDangerAlert(false);
    setSuccesAlert(false);
    setIsDisabled(false);
    setLearningWrongClicks(new Set());
  };

  // Refy dla obsługi klawiatury (zawsze aktualna wersja funkcji)
  const answerChangeRef = useRef(answerChange);
  answerChangeRef.current = answerChange;
  const nextQuestionRef = useRef(nextQuestion);
  nextQuestionRef.current = nextQuestion;
  const answerOrderRef = useRef([0, 1, 2]);

  // Skróty klawiszowe: 1/2/3 → wybór odpowiedzi, Enter → następne pytanie
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA") return;
      if (endTest || showWrongAnswers) return;
      if (!isDisabled && currentTest[currentQuestion]) {
        if (e.key === "1") answerChangeRef.current(answerOrderRef.current[0]);
        else if (e.key === "2") answerChangeRef.current(answerOrderRef.current[1]);
        else if (e.key === "3") answerChangeRef.current(answerOrderRef.current[2]);
      }
      if (isDisabled && (dangerAlert || succesAlert)) {
        if (e.key === "Enter") nextQuestionRef.current();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isDisabled, endTest, currentQuestion, currentTest, dangerAlert, succesAlert, showWrongAnswers]);

  const handleChangeLimit = (event) => {
    setIsManualLimit(true);
    let { value, min, max } = event.target;
    value = Math.max(Number(min), Math.min(Number(max), Number(value)));
    if (value === 0) {
      setMaxQuestions("");
      return;
    }
    setMaxQuestions(value);
  };

  const handleClickAudio = () => setAudioOn(!audio);
  const refreshPage = () => window.location.reload(false);

  const startMistakesReview = () => {
    if (wrongAnswers.length === 0) return;
    const pool = [...wrongAnswers];
    const poolSize = pool.length;
    const drawData = draw(pool, poolSize);
    if (drawData) {
      setFullFilteredLength(poolSize);
      setCurrentTest(drawData);
      setMaxQuestions(poolSize);
      resetQuizState();
      setIsMistakesReview(true);
      clearPausedSession();
      setPausedSession(null);
    }
  };

  // Tryb egzaminu: 40 pytań (10 z sygnalizacji + 30 pozostałe)
  const startExamMode = () => {
    const sygnalizacjaPool = allQuestions.filter(q =>
      q.category.includes("sygnalizacja") && !q.category.includes("81")
    );
    const otherPool = allQuestions.filter(q =>
      !q.category.includes("sygnalizacja") && !q.category.includes("81")
    );
    if (sygnalizacjaPool.length < EXAM_SYGNALIZACJA_COUNT || otherPool.length < EXAM_TOTAL_COUNT - EXAM_SYGNALIZACJA_COUNT) return;

    const examSyg = draw(sygnalizacjaPool, EXAM_SYGNALIZACJA_COUNT);
    const examOther = draw(otherPool, EXAM_TOTAL_COUNT - EXAM_SYGNALIZACJA_COUNT);
    const combined = draw([...examSyg, ...examOther], EXAM_TOTAL_COUNT);

    if (combined) {
      setCurrentTest(combined);
      setMaxQuestions(EXAM_TOTAL_COUNT);
      setFullFilteredLength(EXAM_TOTAL_COUNT);
      resetQuizState();
      setExamMode(true);
      setSearchQuery("");
      clearPausedSession();
      setPausedSession(null);
    }
  };

  const handleResetStats = () => {
    if (!window.confirm("Usunąć całą historię sesji i statystyki pytań?\nGwiazdki (⭐) zostaną zachowane.")) return;
    localStorage.removeItem(STORAGE_KEYS.sessionHistory);
    localStorage.removeItem(STORAGE_KEYS.questionStats);
    setStarredIds((prev) => {
      setCategoryLimits((limits) => ({ ...limits }));
      return prev;
    });
    window.location.reload();
  };

  const resumeSession = () => {
    const s = pausedSession;
    if (!s) return;
    resumingRef.current = true;
    setCurrentTest(s.currentTest);
    setCurrentQuestion(s.currentQuestion);
    setMaxQuestions(s.maxQuestions);
    setFullFilteredLength(s.maxQuestions);
    setCorectAnswers(s.correctAnswers);
    setInCorrectAnswers(s.inCorrectAnswers);
    setWrongAnswers(s.wrongAnswers || []);
    setTest(s.test || ["all"]);
    setExamMode(s.examMode || false);
    setWeakestMode(s.weakestMode || false);
    setIsMistakesReview(s.isMistakesReview || false);
    setLearningMode(s.learningMode || false);
    setTotalAnswered(s.totalAnswered || 0);
    setHasSygnalizacjaError(s.hasSygnalizacjaError || false);
    setEndTest(false);
    setDangerAlert(false);
    setSuccesAlert(false);
    setIsDisabled(false);
    setSelectedAnswerIndex(null);
    setIsAnswerCorrect(null);
    setShowWrongAnswers(false);
    setSearchQuery("");
  };

  const handleToggleStar = (question) => {
    const newIds = toggleStarred(question);
    setStarredIds(newIds);
    setCategoryLimits((prev) => ({ ...prev, starred: newIds.size }));
  };

  // Zapis sesji po zakończeniu testu (nie w trybie nauki, retry błędów, trybie trudnych pytań ani poniżej progu)
  useEffect(() => {
    if (!endTest || learningMode || maxQuestions === 0) return;
    if (isMistakesReview || weakestMode) return;
    if (maxQuestions < MIN_QUESTIONS_FOR_STATS) return;
    const percentage = Math.round((correctAnswers / maxQuestions) * 100);
    saveSession({
      date: new Date().toISOString(),
      categories: [...test],
      correct: correctAnswers,
      total: maxQuestions,
      percentage,
      passed: percentage >= 75 && !hasSygnalizacjaError,
      examMode,
    });
  }, [endTest]); // eslint-disable-line react-hooks/exhaustive-deps

  const getDifficultPool = () => {
    const base = allQuestions.filter(q => !q.category.includes("81"));
    const statWeak = getWeakestQuestions(base);
    const statWeakSet = new Set(statWeak.map(q => getQuestionId(q)));
    const starredPool = base.filter(q => starredIds.has(getQuestionId(q)) && !statWeakSet.has(getQuestionId(q)));
    return [...statWeak, ...starredPool];
  };

  const startWeakestMode = () => {
    const pool = getDifficultPool();
    if (pool.length === 0) return;
    const poolSize = Math.min(pool.length, 30);
    const drawData = draw(pool, poolSize);
    if (drawData) {
      setCurrentTest(drawData);
      setMaxQuestions(poolSize);
      setFullFilteredLength(poolSize);
      resetQuizState();
      setWeakestMode(true);
      setExamMode(false);
      setSearchQuery("");
      clearPausedSession();
      setPausedSession(null);
    }
  };

  useEffect(() => {
    const getQuizData = async () => {
      try {
        const response = await fetch(process.env.PUBLIC_URL + "/questions.json");
        if (!response.ok) return;
        const data = await response.json();
        const questions = data.questions || [];
        if (questions.length === 0) return;

        const normalized = questions.map((q) => {
          const cats = Array.isArray(q.category) ? q.category : [q.category];
          return { ...q, category: cats.map((c) => String(c)) };
        });
        setAllQuestions(normalized);

        // Przepięcie zapisanych statystyk i gwiazdek z treści pytania na `id`.
        // Musi pójść przed odczytem gwiazdek — stan startowy wczytał stare klucze.
        const migration = migrateStorageToIds(normalized);
        if (migration) {
          console.info("Migracja danych do identyfikatorów pytań:", migration);
        }
        // Pauza zapisana starszą wersją nie ma `id` — podmieniamy na aktualne pytania
        setPausedSession((prev) => (prev ? remapPausedSession(prev, normalized) : prev));

        const currentStarred = getStarredIds();
        setStarredIds(currentStarred);
        const limits = { all: 0, starred: 0 };
        normalized.forEach((q) => {
          const cats = q.category;
          if (cats.includes("81")) {
            limits["81"] = (limits["81"] || 0) + 1;
            return;
          }
          limits.all++;
          if (currentStarred.has(getQuestionId(q))) limits.starred++;
          cats.forEach((cat) => { limits[cat] = (limits[cat] || 0) + 1; });
        });
        setCategoryLimits(limits);
      } catch (err) {
        console.error("Błąd ładowania pytań:", err);
      }
    };
    getQuizData();
  }, []);

  useEffect(() => {
    if (allQuestions.length === 0) return;
    if (examMode) return;
    if (weakestMode) return;
    if (resumingRef.current) { resumingRef.current = false; return; }

    const currentStarred = getStarredIds();
    let filtered = allQuestions.filter((q) => {
      const cats = q.category;
      if (cats.includes("81")) return test.includes("81");
      if (test.includes("starred")) return currentStarred.has(getQuestionId(q));
      if (test.includes("all")) return true;
      return cats.some((c) => test.includes(c));
    });

    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      filtered = filtered.filter(
        (item) =>
          item.question.toLowerCase().includes(q) ||
          item.content.some((a) => a.toLowerCase().includes(q))
      );
    }

    if (filtered.length === 0) {
      setCurrentTest([]);
      setMaxQuestions(0);
      resetQuizState();
      return;
    }

    const poolSize = filtered.length;
    setFullFilteredLength(poolSize);
    const drawData = draw(filtered, poolSize);
    if (drawData) {
      setCurrentTest(drawData);
      setMaxQuestions((prev) => {
        if (isManualLimit && prev !== "" && prev !== null) return Math.min(prev, poolSize);
        return Math.min(30, poolSize);
      });
      resetQuizState();
    }
  }, [test, allQuestions, searchQuery]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div className={`app-shell bg-container visual-${visualStyle} container mx-auto min-h-screen pb-5 flex flex-col content-center justify-center text-blue-50 transition-colors duration-500 ease-in-out ${theme === "light" ? "light-mode" : ""}`}>
      <Header />
      <div className="top-controls flex justify-center items-center gap-2">
        <StyleToggle visualStyle={visualStyle} toggleVisualStyle={toggleVisualStyle} />
        <ThemeToggle theme={theme} toggleTheme={toggleTheme} />
        <SoundOnOff handleClickAudio={handleClickAudio} audio={audio} />
        <button
          className={`control-btn learning-btn ${learningMode ? "active" : ""}`}
          onClick={() => setLearningMode(l => !l)}
          title={learningMode ? "Wyłącz tryb nauki" : "Włącz tryb nauki (poprawna odpowiedź jest oznaczona, statystyki wyłączone)"}
        >
          <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
          </svg>
        </button>
        <button
          className={`control-btn ${showHistory ? "active" : ""}`}
          onClick={() => { setShowHistory(h => !h); setShowMap(false); }}
          title="Historia sesji"
        >
          <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        </button>
        <button
          className={`control-btn ${showMap ? "active" : ""}`}
          onClick={() => { setShowMap(m => !m); setShowHistory(false); }}
          title="Mapa postępów"
        >
          <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" />
          </svg>
        </button>
        <Refresh refreshPage={refreshPage} />
      </div>

      {/* Pasek trybu egzaminu */}
      {examMode && (
        <div className="exam-mode-banner">
          TRYB EGZAMINU &nbsp;·&nbsp; {EXAM_TOTAL_COUNT} pytań &nbsp;·&nbsp; min. 75% + brak błędów z Sygnalizacji
        </div>
      )}
      {/* Pasek trybu najsłabszych pytań */}
      {weakestMode && !examMode && (
        <div className="weakest-mode-banner">
          TRUDNE PYTANIA &nbsp;·&nbsp; ćwicz to, co sprawia Ci trudność
        </div>
      )}
      {/* Pasek trybu nauki */}
      {learningMode && !examMode && (
        <div className="learning-mode-banner">
          TRYB NAUKI &nbsp;·&nbsp; poprawna odpowiedź oznaczona · statystyki wyłączone
        </div>
      )}

      {showHistory && (
        <div className="flex justify-center flex-grow p-4">
          <div className="w-full max-w-2xl">
            <SessionHistory />
            <button className="reset-stats-btn" onClick={handleResetStats}>Resetuj statystyki</button>
          </div>
        </div>
      )}

      {showBriefing && allQuestions.length > 0 && (
        <div className="flex justify-center flex-grow px-4 pb-4 pt-2">
          <div className="w-full max-w-3xl">
            <button className="briefing-close-btn" onClick={() => setShowBriefing(false)}>← Wróć do quizu</button>
            <PreExamBriefing
              allQuestions={allQuestions}
              weakCount={getDifficultPool().length}
              onStartExam={() => { setShowBriefing(false); startExamMode(); }}
              onStudyWeak={() => { setShowBriefing(false); startWeakestMode(); }}
            />
          </div>
        </div>
      )}

      {showMap && allQuestions.length > 0 && (
        <div className="flex justify-center flex-grow px-4 pb-4 pt-2">
          <MetroMap allQuestions={allQuestions} />
        </div>
      )}

      {!showHistory && !showMap && !showBriefing && (
        <>
          <div className="flex justify-center flex-grow p-4">
            <div className="setup-panel glass-card w-full max-w-2xl p-6 text-center">
              <LimitOfquestions handleChangeLimit={handleChangeLimit} maxQuestions={examMode ? EXAM_TOTAL_COUNT : maxQuestions} currentTest={currentTest} poolSize={fullFilteredLength} disabled={examMode}>
                <ChoiceTest handleTest={handleTest} test={examMode ? ["all"] : test} categories={CATEGORIES} categoryLimits={categoryLimits} disabled={examMode} />
              </LimitOfquestions>
              <SearchBar
                value={searchQuery}
                onChange={setSearchQuery}
                disabled={examMode || weakestMode}
                resultCount={fullFilteredLength}
              />

              {/* Wznów przerwany test */}
              {pausedSession && totalAnswered === 0 && (
                <div className="resume-row">
                  <button className="resume-btn" onClick={resumeSession}>
                    ▶ Wznów test — pytanie {pausedSession.currentQuestion + 1}/{pausedSession.maxQuestions}
                    <span className="resume-btn-time">
                      {new Date(pausedSession.savedAt).toLocaleDateString("pl-PL", { day: "2-digit", month: "2-digit" })} · {new Date(pausedSession.savedAt).toLocaleTimeString("pl-PL", { hour: "2-digit", minute: "2-digit" })}
                    </span>
                  </button>
                  <button
                    className="resume-discard-btn"
                    onClick={() => { clearPausedSession(); setPausedSession(null); }}
                    title="Odrzuć i zacznij od początku"
                  >Zacznij od nowa</button>
                </div>
              )}

              {/* Przyciski trybów */}
              {allQuestions.length > 0 && (
                <div className="mt-4 flex flex-col gap-2">
                  <button
                    className="briefing-mode-btn"
                    onClick={() => { setShowBriefing(true); setShowMap(false); setShowHistory(false); }}
                  >
                    📋 Przed egzaminem — sprawdź gotowość
                  </button>
                  <button className={`exam-mode-btn ${examMode ? "active" : ""}`} onClick={examMode ? refreshPage : startExamMode}>
                    {examMode
                      ? "Zakończ egzamin"
                      : `Tryb Egzaminu — ${EXAM_TOTAL_COUNT} pytań (${EXAM_SYGNALIZACJA_COUNT} z Sygnalizacji)`}
                  </button>
                  {(() => {
                    const difficultCount = weakestMode ? 0 : getDifficultPool().length;
                    return (
                      <button
                        className={`weakest-mode-btn ${weakestMode ? "active" : ""}`}
                        onClick={weakestMode ? refreshPage : startWeakestMode}
                        disabled={!weakestMode && difficultCount === 0}
                        title={difficultCount === 0 ? "Oznacz pytania gwiazdką lub odpowiedz na kilka pytań" : ""}
                      >
                        {weakestMode
                          ? "Zakończ tryb trudnych pytań"
                          : `Trudne pytania${difficultCount > 0 ? ` (${difficultCount})` : " — brak danych"}`}
                      </button>
                    );
                  })()}
                  {!weakestMode && (
                    <p className="difficult-hint">
                      Pytanie trafia tu po 2 błędach z rzędu. Znika po 2 poprawnych z rzędu — każdy błąd resetuje licznik.
                    </p>
                  )}
                </div>
              )}
            </div>
          </div>
        </>
      )}

      {!showHistory && !showMap && !showBriefing && (
        showWrongAnswers ? (
          <WrongAnswers wrongAnswers={wrongAnswers} startMistakesReview={startMistakesReview} />
        ) : currentTest.length === 0 ? null : (
          <>
            <Quiz currentTest={currentTest} currentQuestion={currentQuestion} answerChange={answerChange} isDisabled={isDisabled} selectedAnswerIndex={selectedAnswerIndex} isAnswerCorrect={isAnswerCorrect} onAnswerOrderChange={(order) => { answerOrderRef.current = order; }} learningMode={learningMode} correctAnswerIndex={currentTest[currentQuestion]?.correct} starredIds={starredIds} onToggleStar={handleToggleStar} learningWrongClicks={learningWrongClicks}>
              {dangerAlert && <DangerAlert answers={currentTest[currentQuestion].content} correctAnswer={currentTest[currentQuestion].correct} correctDisplayIndex={answerOrderRef.current.indexOf(currentTest[currentQuestion].correct) + 1} nextQuestion={nextQuestion} />}
              {succesAlert && <SuccesAlert nextQuestion={nextQuestion} />}
              {endTest && (
                <EndTestAlert correctAnswers={correctAnswers} inCorrectAnswers={inCorrectAnswers} maxQuestions={maxQuestions} hasSygnalizacjaError={hasSygnalizacjaError} examMode={examMode} learningMode={learningMode} savedToStats={!learningMode && !isMistakesReview && !weakestMode && maxQuestions >= MIN_QUESTIONS_FOR_STATS}>
                  <ResultsButtons
                    onRetry={refreshPage}
                    onShowMistakes={() => { setShowWrongAnswers(true); setEndTest(false); }}
                    onReviewMistakes={startMistakesReview}
                    wrongAnswersCount={wrongAnswers.length}
                    learningMode={learningMode}
                  />
                </EndTestAlert>
              )}
            </Quiz>

            {/* Podpowiedź klawiatury */}
            {!endTest && maxQuestions > 0 && !isDisabled && (
              <div className="kbd-hint">klawisze: 1 · 2 · 3</div>
            )}
            {!endTest && maxQuestions > 0 && isDisabled && (dangerAlert || succesAlert) && (
              <div className="kbd-hint">Enter → następne pytanie</div>
            )}

            {!endTest && maxQuestions > 0 && (
              <ProgressStats correctAnswers={correctAnswers} inCorrectAnswers={inCorrectAnswers} maxQuestions={maxQuestions} learningMode={learningMode} totalAnswered={totalAnswered} />
            )}
          </>
        )
      )}
      <Footer />
    </div>
  );
}

export default App;
